+import { SupportedMimeTypes } from '@proton/shared/lib/drive/constants';
+import * as browser from '@proton/shared/lib/helpers/browser';
+import { isHEICSupported, isJXLSupported, isSupportedImage } from '@proton/shared/lib/helpers/mimetype';
+
+describe('modern image support', () => {
+    afterEach(() => jest.restoreAllMocks());
+
+    const setBrowser = (os: string, name: string, version: string) => {
+        jest.spyOn(browser, 'getOS').mockReturnValue({ name: os, version: '' });
+        jest.spyOn(browser, 'getBrowser').mockReturnValue({ name, version, major: version.split('.')[0] });
+    };
+
+    it.each([
+        ['Mac OS', 'Safari', '17'],
+        ['iOS', 'Mobile Safari', '17.1'],
+    ])('supports HEIC and JXL on %s %s %s', (os, name, version) => {
+        setBrowser(os, name, version);
+        expect(isHEICSupported()).toBe(true);
+        expect(isJXLSupported()).toBe(true);
+        for (const type of [
+            SupportedMimeTypes.heic,
+            SupportedMimeTypes.heics,
+            SupportedMimeTypes.heif,
+            SupportedMimeTypes.heifs,
+            SupportedMimeTypes.jxl,
+        ]) {
+            expect(isSupportedImage(type)).toBe(true);
+        }
+    });
+
+    it.each([
+        ['Mac OS', 'Safari', '16.6'],
+        ['Windows', 'Safari', '17'],
+        ['Mac OS', 'Chrome', '17'],
+    ])('rejects unsupported browser %s %s %s', (os, name, version) => {
+        setBrowser(os, name, version);
+        expect(isHEICSupported()).toBe(false);
+        expect(isJXLSupported()).toBe(false);
+        expect(isSupportedImage(SupportedMimeTypes.heic)).toBe(false);
+        expect(isSupportedImage(SupportedMimeTypes.jxl)).toBe(false);
+    });
+});
